// Author: MiYu. Source burrow and Kodo checks consume live orders, weapons, cargo, persistent buffs and digestion damage.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_orc_cargo_tests <data-root> <fixture> [flow|work|release|manual]");std::wstring mode=argc>3?argv[3]:L"flow";if(mode!=L"flow" && mode!=L"work" && mode!=L"release" && mode!=L"manual")throw std::runtime_error("Unknown Orc cargo mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto point=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto burrow=vm.global("burrow"),kodo=vm.global("kodo"),prey=vm.global("prey");auto b=session.units().at(burrow.bits),k=session.units().at(kodo.bits);auto target=session.units().at(vm.global("siege_target").bits);jass::Value mine;
        require(session.cargoCapacity(burrow.bits)==4 && !session.hasWeapon(burrow.bits),"Empty source burrow was armed or had the wrong capacity");
        if(mode==L"manual"){auto peon=vm.global("peons",0);require(!call("IssueTargetOrder",{burrow,vm.string("load"),vm.global("ally")}).bits,"Burrow load accepted a non-peon");require(call("IssueTargetOrder",{burrow,vm.string("load"),peon}).bits,"Burrow source load order was rejected");session.advance(1);require(call("IsUnitInTransport",{peon,burrow}).bits,"Burrow source load did not direct the peon to board");require(call("IssueImmediateOrder",{burrow,vm.string("standdown")}).bits,"Manual garrison Stand Down failed");session.advance(1);}
        if(mode==L"work"){mine=call("CreateUnit",{call("Player",{vm.integer(15)}),type("ngol"),point(-512),point(256),point(0)});auto peon=vm.global("peons",0);call("RemoveUnit",{vm.global("peons",4)});call("SetUnitPosition",{peon,point(-384),point(256)});require(call("IssueTargetOrder",{peon,vm.string("harvest"),mine}).bits,"Peon source harvest order was rejected");session.advance(1./32);require(session.units().at(peon.bits)->gather.inside,"Work fixture did not enter its real mine");}
        float before=number(target->life);require(call("IssueImmediateOrder",{burrow,vm.string("battlestations")}).bits,"Source Battle Stations order was rejected");session.advance(3);require(b->cargo.size()==4 && session.cargoUsed(burrow.bits)==4 && session.hasWeapon(burrow.bits),"Battle Stations did not fill and arm the four-slot burrow");if(mode==L"flow")require(number(target->life)<before,"Occupied burrow did not fire its real weapon");if(mode==L"work"){auto peon=session.units().at(vm.global("peons",0).bits);require(peon->transport==burrow.bits && peon->cargoReturn.has_value(),"Mining peon was not temporarily recalled into garrison");}auto stationed=b->cargo;require(call("IssueImmediateOrder",{burrow,vm.string("standdown")}).bits,"Source Stand Down order was rejected");session.advance(1);require(b->cargo.empty() && !session.hasWeapon(burrow.bits),"Stand Down did not empty and disarm the burrow");for(auto id:stationed)require(!call("IsUnitLoaded",{vm.handle("unit",id)}).bits,"Stand Down left a peon hidden in cargo");
        if(mode==L"work"){auto peon=vm.global("peons",0);require(session.units().at(peon.bits)->gather.mine==mine.bits,"Temporary Battle Stations did not restore the real mining job");std::cout<<"PASS temporary_garrison_work_resume\n";}else{
            require(!call("IssueTargetOrder",{kodo,vm.string("devour"),vm.global("hero")}).bits && !call("IssueTargetOrder",{kodo,vm.string("devour"),vm.global("ally")}).bits && !call("IssueTargetOrder",{kodo,vm.string("devour"),vm.global("mechanical")}).bits,"Devour accepted a hero, friendly or mechanical target");before=number(session.units().at(prey.bits)->life);require(call("IssueTargetOrder",{kodo,vm.string("devour"),prey}).bits,"Source Devour order was rejected");session.advance(1.25);require(call("IsUnitInTransport",{prey,kodo}).bits && call("GetUnitAbilityLevel",{kodo,type("Bdig")}).bits && call("GetUnitAbilityLevel",{prey,type("Bdvv")}).bits,"Devour did not establish actual cargo and both source buffs");require(number(session.units().at(prey.bits)->life)<before,"Devour did not apply actual source digestion damage");require(!call("IssueImmediateOrderById",{kodo,vm.integer(852049)}).bits,"Devour cargo allowed voluntary unloading");
            if(mode==L"release"){call("KillUnit",{kodo});require(!call("IsUnitLoaded",{prey}).bits && !session.units().at(prey.bits)->digestion && !call("GetUnitAbilityLevel",{prey,type("Bdvv")}).bits,"Kodo death left digestion state on its victim");std::cout<<"PASS devour_carrier_death_release\n";}else{call("SetWidgetLife",{prey,vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(2.5f)))});session.advance(1);require(number(session.units().at(prey.bits)->life)==0 && !call("IsUnitLoaded",{prey}).bits && !call("GetUnitAbilityLevel",{kodo,type("Bdig")}).bits && k->cargo.empty(),"Digestion death did not clear source cargo and buffs");require(vm.global("last_killer").bits==kodo.bits,"Digestion death lost the real Kodo killer");std::cout<<"PASS garrison_fire_standdown_devour_damage_and_death\n";}
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
